package purescript
import (
 "testing"
 rt "gopurs/output/gopurs_runtime"
)
var listopsSink int64
var listopsListSink *Constructor_Test_ListOps_Cons[int64]
func listopsFusedPrototype(n int64) int64 {
 var sum int64
 for n >= 1 {
  if rt.IntMod(n, 2) == 0 { sum = rt.IntAdd(sum, n) }
  n = rt.IntSub(n, 1)
 }
 return sum
}
func TestListopsOracle(t *testing.T) {
 for n := int64(-4); n <= 1025; n++ {
  want := int64(0)
  for i := int64(1); i <= n; i++ { if i % 2 == 0 { want += i } }
  if got := Call_Test_ListOps_sumEvens(n); got != want { t.Fatalf("n=%d got=%d want=%d",n,got,want) }
  if got := listopsFusedPrototype(n); got != want { t.Fatalf("prototype n=%d got=%d want=%d",n,got,want) }
 }
}
func BenchmarkListPipeline(b *testing.B) {
 b.ReportAllocs()
 for i:=0;i<b.N;i++ { listopsSink = Call_Test_ListOps_sumEvens(900) }
}
func BenchmarkListRange(b *testing.B) {
 b.ReportAllocs()
 for i:=0;i<b.N;i++ { listopsListSink = Call_Test_ListOps_go__range(1,900) }
}
func BenchmarkListFilter(b *testing.B) {
 input:=Call_Test_ListOps_go__range(1,900)
 b.ReportAllocs(); b.ResetTimer()
 for i:=0;i<b.N;i++ { listopsListSink = Call_Test_ListOps_filterEvens(input) }
}
func BenchmarkListFold(b *testing.B) {
 input:=Call_Test_ListOps_filterEvens(Call_Test_ListOps_go__range(1,900))
 add:=Get_Data_Semiring_intAdd()
 b.ReportAllocs(); b.ResetTimer()
 for i:=0;i<b.N;i++ { listopsSink = Call_Test_ListOps_foldl__1432417732(add,0,input) }
}
func BenchmarkFusedPrototype(b *testing.B) {
 b.ReportAllocs()
 for i:=0;i<b.N;i++ { listopsSink = listopsFusedPrototype(900) }
}
